@isTest
private class DatabaseDmlObjectListParityTest {
  @isTest static void objectAndListDmlMatchesSalesforce() {
    SObject one = new Account(Name = 'Parity One');
    Database.SaveResult inserted = Database.insert(one);
    System.assert(inserted.isSuccess());
    one.put('Name', 'Parity One Updated');
    System.assert(Database.update(one).isSuccess());
    one.put('Name', 'Parity One Updated Again');
    System.assert(Database.update(one, false).isSuccess());
    one.put('Name', 'Parity One Updated System');
    System.assert(Database.update(one, false, AccessLevel.SYSTEM_MODE).isSuccess());
    System.assertEquals('Parity One Updated System', [SELECT Name FROM Account WHERE Id = :one.Id].Name);
    System.assert(Database.delete(one).isSuccess());
    System.assert([SELECT IsDeleted FROM Account WHERE Id = :one.Id ALL ROWS].IsDeleted);
    System.assert(Database.undelete(one).isSuccess());
    System.assert(![SELECT IsDeleted FROM Account WHERE Id = :one.Id ALL ROWS].IsDeleted);
    System.assert(Database.delete(one, AccessLevel.SYSTEM_MODE).isSuccess());
    System.assert([SELECT IsDeleted FROM Account WHERE Id = :one.Id ALL ROWS].IsDeleted);
    System.assert(Database.undelete(one, AccessLevel.SYSTEM_MODE).isSuccess());
    System.assert(![SELECT IsDeleted FROM Account WHERE Id = :one.Id ALL ROWS].IsDeleted);

    SObject two = new Account(Name = 'Parity Two');
    SObject three = new Account(Name = 'Parity Three');
    List<SObject> records = new List<SObject>{two, three};
    List<Database.SaveResult> insertedList = Database.insert(records);
    System.assertEquals(2, insertedList.size());
    Set<Id> recordIds = new Set<Id>{insertedList[0].getId(), insertedList[1].getId()};
    two.put('Name', 'Parity Two Updated');
    three.put('Name', 'Parity Three Updated');
    System.assertEquals(2, Database.update(records).size());
    two.put('Name', 'Parity Two Updated Again');
    three.put('Name', 'Parity Three Updated Again');
    System.assertEquals(2, Database.update(records, false).size());
    two.put('Name', 'Parity Two Updated System');
    three.put('Name', 'Parity Three Updated System');
    System.assertEquals(2, Database.update(records, AccessLevel.SYSTEM_MODE).size());
    two.put('Name', 'Parity Two Updated Both');
    three.put('Name', 'Parity Three Updated Both');
    System.assertEquals(2, Database.update(records, false, AccessLevel.SYSTEM_MODE).size());
    System.assertEquals(2, [SELECT COUNT() FROM Account WHERE Name IN ('Parity Two Updated Both', 'Parity Three Updated Both')]);
    System.assertEquals(2, Database.delete(records).size());
    Integer deletedCount = 0;
    for (Account row : [SELECT Id, IsDeleted FROM Account WHERE Id IN :recordIds ALL ROWS]) {
      if (row.IsDeleted) deletedCount++;
    }
    System.assertEquals(2, deletedCount);
    System.assertEquals(2, Database.undelete(records).size());
    System.assertEquals(2, [SELECT COUNT() FROM Account WHERE Id IN :recordIds]);
    System.assertEquals(2, Database.delete(records, false).size());
    System.assertEquals(2, Database.undelete(records, AccessLevel.SYSTEM_MODE).size());
    System.assertEquals(2, Database.delete(records, AccessLevel.SYSTEM_MODE).size());
    System.assertEquals(2, Database.undelete(records, false, AccessLevel.SYSTEM_MODE).size());
    System.assertEquals(2, Database.delete(records, false, AccessLevel.SYSTEM_MODE).size());
    deletedCount = 0;
    for (Account row : [SELECT Id, IsDeleted FROM Account WHERE Id IN :recordIds ALL ROWS]) {
      if (row.IsDeleted) deletedCount++;
    }
    System.assertEquals(2, deletedCount);
    System.assertEquals(2, Database.undelete(records, false, AccessLevel.SYSTEM_MODE).size());
  }
}
